const fs = require('node:fs');
const captured = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const pattern = new RegExp(captured.source, captured.flags);
const result = captured.input.match(pattern);
console.log(JSON.stringify(result === null ? null : { matches: Array.from(result), index: result.index, groups: result.groups }));
